function exercisesFor(week, dayRecord, weekNumber, dayNumber) {
  const id = `ai-w${String(weekNumber).padStart(2, '0')}-d${dayNumber}`;
  const placeCorrect = (options, correctIndex) => {
    const correct = options.shift();
    options.splice(correctIndex, 0, correct);
    return options;
  };
  const conceptIndex = (weekNumber + dayNumber - 2) % 3;
  const conceptOptions = placeCorrect([
    [dayRecord.correct, dayRecord.correct],
    [dayRecord.wrongA, `이 선택지는 오늘 사례의 조건과 맞지 않아요. 올바른 기준은 ${dayRecord.correct}`],
    [dayRecord.wrongB, `오늘 예제에서 확인되는 원리는 ${dayRecord.correct}`],
  ], conceptIndex);
  const concept = choice(
    `${id}-concept`, '개념 확인', `${dayRecord.question}\n\n${dayRecord.example}`,
    conceptOptions, conceptIndex, `${dayRecord.title}의 입력·출력·조건을 다시 살펴봐요.`,
    dayRecord.correct,
  );
  const trace = shortAnswer(
    `${id}-trace`, '예제 확인', `${dayRecord.reflection}\n\n${dayRecord.example}`,
    [dayRecord.answer, ...dayRecord.alternatives], '예제에 나온 숫자·자료·조건에서 답을 찾을 수 있어요.',
    `${dayRecord.answer}. ${dayRecord.reflectionExplanation}`,
  );
  const practiceIndex = (weekNumber + dayNumber) % 3;
  const practiceOptions = placeCorrect([
    [dayRecord.action, dayRecord.action],
    [dayRecord.badA, `오늘 상황의 조건을 반영하지 못해요. ${dayRecord.action}`],
    [dayRecord.badB, `더 알맞은 대응은 ${dayRecord.action}`],
  ], practiceIndex);
  const practice = choice(
    `${id}-apply`, '상황에 적용하기', dayRecord.application,
    practiceOptions, practiceIndex, `문제의 목표와 실패했을 때의 영향을 먼저 확인해요.`,
    dayRecord.action,
  );
  return [concept, trace, practice];
}

