function createAiCourseExpansion() {
  const lessons = weeks.map((spec, index) => {
  const week = index + 1;
  const phase = phases.find((item) => week >= item.startWeek && week <= item.endWeek);
  const sessions = spec.days.map((record, dayIndex) => {
    const dayNumber = dayIndex + 1;
    const session = studySession(
      dayNumber,
      record.title,
      `${record.title}의 핵심을 설명하고 예제에 적용해요.`,
      `오늘은 ${record.title}의 원리를 예제로 확인하고 헷갈리기 쉬운 기준을 구분해요.`,
      record.example,
      exercisesFor(spec, record, week, dayNumber),
      'text',
    );
    const practicalActivity = practicalActivities.get(week)?.[dayIndex];
    session.activities = [
      { time: '10~15분', title: '핵심 개념 설명하기', prompt: '예제에서 오늘 개념이 드러나는 부분을 찾아, 그 이유를 한 문장으로 설명해요.' },
      { time: '15~20분', title: '예제 조건 바꿔 보기', prompt: '예제의 숫자·조건·자료를 하나 바꾸고 결과가 어떻게 달라지는지 예상해요.' },
      {
        time: '20~25분',
        title: practicalActivity?.[0] ?? '상황에 적용하기',
        prompt: practicalActivity?.[1] ?? (phase.number >= 4 && phase.number <= 5
          ? '실제 AI 도구 사용은 선택이에요. 써 본다면 개인정보나 기밀이 없는 예제로 요청하고 결과의 근거와 빠진 조건을 확인해요.'
          : '오늘 사례에 결론을 적용하기 전에 확인할 조건이나 근거를 하나 적어요.'),
      },
      { time: '5분', title: '복습 메모', prompt: '새로 배운 점과 아직 헷갈리는 점을 적고, 틀린 문제의 이유를 한 문장으로 정리해요.' },
    ];
    return session;
  });
  const lesson = weeklyLesson({
    id: `ai-week-${String(week).padStart(2, '0')}`,
    topicId: phase.id,
    week,
    title: `${week}주차 · ${spec.title}`,
    objective: spec.objective,
    intro: `${spec.intro} ${spec.rule}`,
    points: spec.days.slice(0, 3).map((record) => `${record.title}${objectParticle(record.title)} 사례로 설명해요.`),
    example: spec.days[0].example,
    sessions,
    difficulty: ['입문', '기초', '기초', '기초', '중급', '중급'][phase.number - 1],
  });
  lesson.showSessionSummary = false;
  return lesson;
  });
  return {
    phases,
    lessonOrder: lessons.map((lesson) => lesson.id),
    existingWeeks: {},
    lessons,
    reviewedWeeks: lessons.map((lesson) => lesson.week),
  };
}

function day(title, example, question, correct, wrongA, wrongB, application, action, badA, badB, reflection, answer, alternatives = [], reflectionExplanation = correct) {
  return { title, example, question, correct, wrongA, wrongB, application, action, badA, badB, reflection, answer, alternatives, reflectionExplanation };
}

function objectParticle(value) {
  const topic = value.trim().replace(/\s*\([^)]*\)$/u, '');
  const last = [...topic].at(-1) ?? '';
  const codePoint = last.codePointAt(0);
  if (codePoint >= 0xac00 && codePoint <= 0xd7a3) {
    return (codePoint - 0xac00) % 28 === 0 ? '를' : '을';
  }
  return /[aeiou]$/i.test(last) ? '를' : '을';
}

